    public static Brush B(string hex){var b=(SolidColorBrush)new BrushConverter().ConvertFromString(hex)!;b.Freeze();return b;}
    static readonly Dictionary<string,ImageSource> Cache=[];
    static ImageSource Pixels(string key,string[] rows,Dictionary<char,string> colors)
    {
        if(Cache.TryGetValue(key,out var image))return image;
        var group=new DrawingGroup();using(var d=group.Open())
        {
            d.DrawRectangle(Brushes.Transparent,null,new Rect(0,0,rows.Max(r=>r.Length),rows.Length));
            for(int y=0;y<rows.Length;y++)for(int x=0;x<rows[y].Length;x++)if(colors.TryGetValue(rows[y][x],out string? color))d.DrawRectangle(B(color),null,new Rect(x,y,1,1));
        }
        group.Freeze();var result=new DrawingImage(group);result.Freeze();Cache[key]=result;return result;
    }
