    public static ImageSource Person(string kind,int facing=0,int step=0)
    {
        string key=$"person-{kind}-{facing}-{step%2}";
        string[] rows=["....####....","...#YYYY#...","..#YYYYYY#..","..########..","...#SSSS#...",facing==1?"...#SSSS#...":"...#BSBS#...","....#SS#....","...#CCCC#...","..#SCCCCS#..","..#SCCCCS#..","...#CCCC#...","....#NN#....",step%2==0?"...#N##N#...":"....#NN#....",step%2==0?"...##..##...":"....##.##..."];
